sys_script_include.script:
var StudentLoginUtils = Class.create();
StudentLoginUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    validateUser: function() {

        var username = this.getParameter('sysparm_username');  // Admin username
        var password = this.getParameter('sysparm_password');  // Always check 1234
        var role = this.getParameter('sysparm_role');          // student / alumni / admin
        var rollno = this.getParameter('sysparm_rollno');      // roll number for student/alumni

        // Password check first
        if (password != '1234') {
            return 'invalid';
        }

        // STUDENT LOGIN
        if (role == 'student') {
            var grStudent = new GlideRecord('student');       
            grStudent.addQuery('number', rollno);           // username field stores roll number
            grStudent.query();
            if (grStudent.next()) {
                return 'valid_student';
            }
        }

        // ALUMNI LOGIN
        if (role == 'alumni') {
            var grAlumni = new GlideRecord('alumni');         // Replace with your actual alumni table name
            grAlumni.addQuery('alumniid', rollno);           // alumniid field
            grAlumni.query();
            if (grAlumni.next()) {
                return 'valid_alumni';
            }
        }

        // ADMIN LOGIN
        if (role == 'admin') {
            if (username == 'admin') {
                return 'valid_admin';
            }
        }

        // If nothing matches
        return 'invalid';
    }

});
